import { post } from '@xernerx/stats';
import { Terminal } from '@xernerx/terminal';

export class TelemetryPoster extends Terminal {
	constructor() {
		super({ scope: 'XS' });
	}

	async run() {
		await post(
			{
				id: 'YOUR_BOT_ID',
				guildCount: 1500,
				userCount: 450000,
				shardCount: 2,
			},
			process.env.XERNERX_API_TOKEN!
		);

		this.info('Posted telemetry snapshot.');
	}
}

new TelemetryPoster().run();
